(()=>{'use strict';
const $=s=>document.querySelector(s),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={brain:'M12 3v18M9 3C5 1 2 6 5 9c-4 4 0 10 4 9M15 3c4-2 7 3 4 6 4 4 0 10-4 9M5 6l4 4m10-4-4 4M5 15l4-3m10 3-4-3',home:'m3 10 9-7 9 7v10H3zM9 20v-7h6v7',calendar:'M4 5h16v16H4zM4 10h16M8 3v4m8-4v4M8 14h2m4 0h2m-8 3h2',pill:'m8 16 8-8M5 19a5 5 0 0 1 0-7l7-7a5 5 0 0 1 7 7l-7 7a5 5 0 0 1-7 0Z',music:'M9 18V5l11-2v13M9 5l11-2M9 18a3 3 0 1 1-3-3c2 0 3 1 3 3Zm11-2a3 3 0 1 1-3-3c2 0 3 1 3 3Z',image:'M3 3h18v18H3zM3 16l6-6 5 5 3-3 4 4M16 7h.01',phone:'M5 3h4l2 5-3 2a13 13 0 0 0 6 6l2-3 5 2v4c0 2-2 3-4 2C9 19 5 15 3 7c-1-2 0-4 2-4Z',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',users:'M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 22v-4a7 7 0 0 1 14 0v4M17 3a4 4 0 0 1 0 8m2 4a5 5 0 0 1 3 5v2',chart:'M3 3v18h18M7 16l4-5 4 2 6-9',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM12 7v6m0 3h.01',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8',chat:'M3 3h18v14H8l-5 4zM7 8h10m-10 4h7',logout:'M9 3H3v18h6M8 12h13m-5-5 5 5-5 5',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',heart:'M12 21 3 12C-2 4 8-2 12 6 16-2 26 4 21 12z',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10ZM12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',book:'M12 5C8 2 3 3 2 4v16c3-2 7-2 10 0 3-2 7-2 10 0V4c-3-2-7-2-10 1zM12 5v15',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',puzzle:'M3 3h6a3 3 0 1 0 6 0h6v6a3 3 0 1 0 0 6v6h-6a3 3 0 1 1-6 0H3v-6a3 3 0 1 0 0-6z',check:'m5 12 4 4L20 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v6l4 2',edit:'m4 16 12-12 4 4L8 20H4zM14 6l4 4',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',plus:'M12 4v16M4 12h16',menu:'M3 6h18M3 12h18M3 18h18',more:'M5 12h.01M12 12h.01M19 12h.01',volume:'M3 9h4l5-4v14l-5-4H3zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',star:'m12 2 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1z',doctor:'M4 3v6a5 5 0 0 0 10 0V3M2 3h4m6 0h4M9 14v2a5 5 0 0 0 10 0v-3M19 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',mail:'M3 5h18v14H3zM3 5l9 8 9-8',drop:'M12 2C9 7 5 12 5 16a7 7 0 0 0 14 0c0-4-4-9-7-14Z',walk:'M13 3h.01M10 8l4-1 3 5h4M14 7l-3 8 5 6M11 15l-5 6M10 8l-4 5H2',food:'M4 2v8m3-8v8m3-8v8M4 7h6M7 10v12M18 2c-5 4-5 9 0 10v10M18 2v10',close:'M5 5l14 14M19 5 5 19',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4',leaf:'M20 3C3 1 1 13 7 18s14 1 13-15ZM5 21 17 8',stop:'M5 5h14v14H5z'};
const icon=(n,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const brand=()=>`<span class="brand">${icon('brain',32)}<span>Manas-Mitra</span></span>`;
const dateKey=()=>new Date().toLocaleDateString('en-CA');const todayDate=()=>new Date().toISOString().slice(0,10);
const DEFAULT_SETTINGS={language:'en',theme:'light',font:'medium',contrast:false,reducedMotion:false,largeTargets:false,autoSpeak:true,speed:.9,volume:.85,voice:'coral',notifications:false};
function defaultData(){return {profile:{name:'Aaji',age:72,city:'Ahmedabad',caregiver:'Priya',doctor:'Dr. Meera Shah',phone:'',emergencyPhone:'',doctorPhone:''},settings:{...DEFAULT_SETTINGS},tasks:[['08:00','morningMedicine','pill','Medicine'],['08:30','Breakfast','food','Meal'],['10:00','memoryGame','brain','Activity'],['11:30','water','drop','Water'],['13:00','lunch','food','Meal'],['17:00','walk','walk','Exercise'],['18:00','familyCall','phone','Family'],['20:00','eveningMedicine','pill','Medicine']].map((t,i)=>({id:i+1,time:t[0],title:t[1],icon:t[2],type:t[3],repeat:'Daily',priority:t[3]==='Medicine'?'High':'Normal',active:true,status:'pending',completionDate:null})),memories:[{id:1,title:'Our family garden',description:'You love spending quiet mornings in the garden with Priya. The sunflowers are a favorite.',category:'Family',art:'🌻',date:'A favorite place'},{id:2,title:'A trip to Manali',description:'Your family visited the mountains together in 2019. You enjoyed the fresh air and the beautiful views.',category:'Places',art:'🏔️',date:'2019'},{id:3,title:'Sunday melodies',description:'Listening to old Hindi songs has always made Sunday mornings feel special.',category:'Favorites',art:'🎵',date:'Every Sunday'}],gameResults:[],conversations:[],notes:[],appointments:[],careMessages:[],mood:null,updatedAt:Date.now()}}
function readDemo(){try{let stored=JSON.parse(localStorage.getItem('mm-v2-demo'));if(stored?.profile&&Array.isArray(stored.tasks))return {...defaultData(),...stored,settings:{...DEFAULT_SETTINGS,...stored.settings}}}catch{}return defaultData()}
const S={role:null,view:'home',data:readDemo(),user:null,health:null,game:null,gameType:null,filter:'All',voice:'idle',chatBusy:false,dirty:false,music:null};
const T=k=>MM_TEXT[S.data.settings.language]?.[k]||MM_TEXT.en[k]||k;const taskTitle=t=>T(t.title);const lang=()=>MM_LANGUAGES[S.data.settings.language]||MM_LANGUAGES.en;const greeting=()=>S.data.settings.language==='en'?(new Date().getHours()<12?'Good morning':new Date().getHours()<17?'Good afternoon':'Good evening'):T('greeting');
const timeLabel=t=>{let [h,m]=t.split(':');return new Date(2026,1,1,Number(h),Number(m)).toLocaleTimeString(lang().code,{hour:'numeric',minute:'2-digit'})};const timeStamp=t=>new Date(t).toLocaleTimeString(lang().code,{hour:'numeric',minute:'2-digit'});
function toast(m){let el=$('#toast');el.textContent=m;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200)}
async function request(path,{method='GET',body,signal}={}){let r=await fetch('/api'+path,{method,headers:body&&!(body instanceof FormData)?{'Content-Type':'application/json'}:{},body:body instanceof FormData?body:body?JSON.stringify(body):undefined,credentials:'same-origin',signal});let d=await r.json().catch(()=>({error:'Service unavailable'}));if(!r.ok)throw new Error(d.error||'Unable to connect');return d}
async function persist(){S.data.updatedAt=Date.now();if(!S.user){localStorage.setItem('mm-v2-demo',JSON.stringify(S.data));return}try{const saved=await request('/state',{method:'PUT',body:S.data});S.data.revision=saved.revision;S.data.memories=saved.memories;S.dirty=false}catch(e){S.dirty=true;toast('Your change is kept in this session. Reconnect to save it securely.')}}
function settingsApply(){let s=S.data.settings;document.documentElement.lang=s.language;document.documentElement.dataset.theme=s.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):s.theme;document.documentElement.className=[`font-${s.font}`,s.contrast?'contrast':'',s.reducedMotion?'reduced-motion':'',s.largeTargets?'large-targets':''].join(' ')}
function languageSelect(){return `<select class="language-control" data-setting="language" aria-label="${E(T('language'))}">${Object.entries(MM_LANGUAGES).map(([k,v])=>`<option value="${k}" ${S.data.settings.language===k?'selected':''}>${E(v.label)}</option>`).join('')}</select>`}
function avatar(size=''){return `<span class="avatar ${size}"><img src="public/assets/garden-portrait.png" alt="Fictional patient portrait"></span>`}
function head(title,sub,action=''){return `<div class="page-head"><div><h1>${E(title)}</h1><p>${E(sub)}</p></div>${action}</div>`}
function navItems(){return S.role==='patient'?[['home','home'],['games','brain'],['day','calendar'],['reminders','bell'],['memories','image'],['talk','chat'],['music','music'],['settings','settings']]:S.role==='caregiver'?[['home','home'],['patient','users'],['progress','chart'],['reminders','bell'],['appointments','calendar'],['messages','mail'],['memories','image'],['settings','settings']]:[['home','doctor'],['patient','users'],['progress','chart'],['notes','book'],['appointments','calendar'],['messages','mail'],['settings','settings']]}
function landing(){return `<div class="landing"><header class="landing-nav">${brand()}<nav class="landing-links"><a href="#main">Home</a><a href="#about">Our approach</a><a href="#portals">For your family</a></nav>${languageSelect()}<button class="btn small" data-action="signin">Sign in ${icon('arrow',15)}</button></header><main id="main"><section class="landing-hero"><div class="hero-surface"><img class="hero-photo" src="public/assets/garden-portrait.png" alt="An older woman enjoying a peaceful morning in her garden" width="1536" height="1024"><div class="hero-copy"><div class="eyebrow">A little support. A lot of heart.</div><h1>Better memories.<br>Brighter<br><span>tomorrows.</span></h1><p>A caring companion for everyday life. Find joy in small moments, keep your mind active, and stay connected to the people you love.</p><a class="btn large" href="#portals">Find your space ${icon('arrow',18)}</a><div class="hero-foot">${icon('heart',16)} Thoughtfully made for you and your family</div></div></div></section><section class="feature-row" id="about"><div class="feature"><span class="feature-icon">${icon('brain',28)}</span><div><h3>Cognitive games</h3><p>Gentle, engaging activities at your own pace.</p></div></div><div class="feature"><span class="feature-icon">${icon('calendar',27)}</span><div><h3>Everyday routines</h3><p>A helping hand for the little things in your day.</p></div></div><div class="feature"><span class="feature-icon">${icon('users',28)}</span><div><h3>Connected care</h3><p>A shared space for family and your care team.</p></div></div></section><section id="portals" class="portal-section"><div class="portal-intro"><div class="eyebrow">Everyone has a place here</div><h2>Who are you here for?</h2><p>Choose your space. We’ll take it from here.</p></div><div class="portal-grid">${[['patient','👵','I am a patient','Your day, memories, and moments of joy.'],['caregiver','👩','I am a caregiver','Support someone you love, every day.'],['doctor','👩‍⚕️','I am a doctor','Stay informed. Help shape better care.']].map(([role,art,title,desc])=>`<article class="portal-card"><div class="portal-symbol art-emoji">${art}</div><h3>${title}</h3><p>${desc}</p><button class="btn soft" data-role="${role}">Open ${T(role).toLowerCase()} space ${icon('arrow',16)}</button></article>`).join('')}</div></section><section class="landing-about"><strong>Small steps. Shared moments. Meaningful care.</strong><br>Daily support for people living with memory difficulties and the people beside them.</section></main><footer class="landing-footer">${brand()}<span>12 languages · 72 game levels · Three connected spaces</span><span>Made with care ♡</span></footer></div>`}
function shell(){let nav=navItems(),title=S.role==='patient'?S.data.profile.name:S.role==='caregiver'?S.data.profile.caregiver:S.data.profile.doctor;return `<div class="app-layout"><aside class="sidebar" id="sidebar">${brand()}<div class="side-caption">${T(S.role)} ${S.user?'portal':'demo'}</div><nav class="side-nav" aria-label="Main navigation">${nav.map(([key,i])=>`<button class="nav-item ${S.view===key?'active':''}" data-nav="${key}" ${S.view===key?'aria-current="page"':''}>${icon(i,21)} ${T(key==='home'&&S.role!=='patient'?'overview':key)}</button>`).join('')}</nav><div class="side-footer"><button class="sidebar-help" data-nav="help">${icon('shield',20)} ${T('help')} / SOS</button><div class="side-user">${S.role==='patient'?avatar('mini'):`<span class="avatar mini">${E(title.charAt(0))}</span>`}<div><strong>${E(title)}</strong><small>${S.user?'Signed in securely':'Demo space'}</small></div><button class="icon-btn" data-action="leave" aria-label="Switch portal">${icon('logout',18)}</button></div></div></aside><div class="page-wrap"><header class="app-topbar">${brand()}<div class="top-date">${new Date().toLocaleDateString(lang().code,{weekday:'long',month:'long',day:'numeric'})}<small id="clock"></small></div><div class="top-controls"><span class="role-badge">${T(S.role)}</span>${languageSelect()}<button class="icon-btn" data-nav="reminders" aria-label="Reminders">${icon('bell',20)}</button><button class="icon-btn" data-nav="settings" aria-label="Accessibility and settings">${icon('settings',20)}</button>${avatar('mini')}</div><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu',22)}</button></header><main id="main" class="workspace" tabindex="-1">${page()}</main><footer class="app-footer"><div class="between"><span>Small steps every day make a big difference. ♡</span><span class="backend-status"><i class="dot"></i>${!navigator.onLine?'Offline · on this device':S.user?'Secure account':S.health?.ai?'Demo profile · AI connected':'Demo profile · on this device'}</span></div></footer></div></div><nav class="mobile-nav" aria-label="Bottom navigation">${(S.role==='patient'?[['home','home'],['games','brain'],['day','calendar'],['reminders','bell'],['more','menu']]:[['home','home'],['patient','users'],['progress','chart'],['messages','mail'],['more','menu']]).map(([key,i])=>`<button data-nav="${key}" class="${S.view===key?'active':''}">${icon(i,21)} ${T(key==='home'&&S.role!=='patient'?'overview':key)}</button>`).join('')}</nav>`}
function page(){return ({home:S.role==='patient'?patientHome:careHome,patient:patientDetails,games:gamesPage,day:dayPage,reminders:remindersPage,memories:memoriesPage,talk:chatPage,music:musicPage,help:helpPage,settings:settingsPage,progress:progressPage,notes:notesPage,appointments:appointmentsPage,messages:messagesPage,more:morePage}[S.view]||patientHome)()}
function render(){settingsApply();$('#app').innerHTML=S.role?shell():landing();const log=$('#chat-log');if(log)log.scrollTop=log.scrollHeight;tickClock()}
function go(view){MM_VOICE.stop();if(S.game&&view!=='games')S.game=null;S.view=view;S.filter='All';render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true})}
function pendingTasks(){return S.data.tasks.filter(t=>t.active&&!(t.status==='done'&&t.completionDate===dateKey())).sort((a,b)=>a.time.localeCompare(b.time))}
function completed(t){return t.status==='done'&&t.completionDate===dateKey()}
function routineRows(tasks,manage=false){return tasks.length?tasks.map(t=>`<div class="routine-item"><span class="routine-symbol">${icon(t.icon||'bell',23)}</span><div class="routine-copy"><strong>${E(taskTitle(t))}</strong><small>${timeLabel(t.time)}${manage?' · '+E(t.repeat):''}${t.snoozedUntil>Date.now()?' · Snoozed until '+timeStamp(t.snoozedUntil):''}</small></div><div class="routine-actions">${completed(t)?`<span class="tag">${icon('check',12)} ${T('done')}</span>`:t.title==='memoryGame'&&!manage?`<button class="link-btn" data-nav="games">${T('play')} ${icon('arrow',13)}</button>`:`<span class="tag neutral">${t.active?T('pending'):'Paused'}</span>`}${manage?`<button class="mini-action" data-action="task-done" data-id="${t.id}" aria-label="${completed(t)?'Undo completion':'Mark complete'} ${E(taskTitle(t))}">${icon(completed(t)?'back':'check',16)}</button><button class="mini-action" data-action="task-snooze" data-id="${t.id}" aria-label="Snooze ${E(taskTitle(t))}">${icon('clock',16)}</button><button class="mini-action" data-action="task-edit" data-id="${t.id}" aria-label="Edit ${E(taskTitle(t))}">${icon('edit',16)}</button>`:''}</div></div>`).join(''):`<div class="empty">Your plan is clear for now.</div>`}
function patientHome(){let n=pendingTasks()[0];return `<section class="card greeting-card">${avatar()}<div><h1>${greeting()}, ${E(S.data.profile.name)} <span style="color:#e9b83d">☀</span></h1><p>It’s a lovely day to take one little step.</p></div><div class="date"><strong>${new Date().toLocaleDateString(lang().code,{day:'numeric',month:'short',year:'numeric'})}</strong>${T('today')} is yours</div></section><div class="dashboard-grid"><section class="activity-grid" aria-label="Daily activities">${[['games','brain','tile-blue',T('games'),'Keep your mind active'],['day','calendar','tile-green',T('day'),'View your routine'],['reminders','pill','tile-yellow',T('reminders'),'Medication, water & more'],['music','music','tile-purple',T('music'),'Calm your mind'],['memories','image','tile-sky',T('memories'),'Your happy moments'],['help','phone','tile-peach',T('help'),'Someone is here for you']].map(([v,i,c,title,sub])=>`<button class="activity-tile ${c}" data-nav="${v}"><span class="activity-icon">${icon(i,44)}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</section><aside class="stack dashboard-side"><section class="card companion-mini"><div class="companion-head"><img src="public/assets/avatar.png" alt="Friendly companion" width="54" height="64"><div><h2>Always here for you</h2><span class="tag">Your AI companion</span></div></div><p>${T('askMe')}</p><button class="btn" data-nav="talk">${icon('mic',19)} ${T('talk')}</button></section><section class="card next-card"><div class="eyebrow">Up next in your day</div><div class="flex"><span class="next-icon">${icon(n?.icon||'sun',27)}</span><div><h3>${n?E(taskTitle(n)):'A moment for yourself'}</h3><p style="margin:0">${n?timeLabel(n.time):'Your plan is complete.'}</p></div></div><button class="link-btn" data-nav="day" style="margin-top:17px">See your daily plan ${icon('arrow',17)}</button></section><div class="gentle-note">${icon('heart',19)} ${T('takeTime')}</div></aside></div><div class="home-lower"><section><div class="section-head"><h2>${T('today')}’s routine</h2><button class="link-btn" data-nav="day">View all ${icon('arrow',15)}</button></div><div class="card routine-list">${routineRows(S.data.tasks.slice(0,4))}</div></section><section class="card quote-panel"><span style="font-size:2rem">🌿</span><h3>How are you feeling today?</h3><p>A small check-in, just for you.</p><div class="mood-options">${[['good','😊','Good'],['okay','😌','Okay'],['low','😔','A little low']].map(([k,a,l])=>`<button class="${S.data.mood===k?'selected':''}" data-action="mood" data-id="${k}"><span>${a}</span>${l}</button>`).join('')}</div></section></div>`}
function dayPage(){return `${head(T('day'),'A familiar rhythm, one moment at a time.',`<button class="btn" data-action="task-add">${icon('plus',17)} ${T('add')}</button>`)}<div class="content-grid"><section class="card routine-list routine-manage">${routineRows([...S.data.tasks].sort((a,b)=>a.time.localeCompare(b.time)),true)}</section><aside class="stack"><div class="card panel"><h2>Your daily progress</h2><div class="between"><strong>${S.data.tasks.filter(completed).length} of ${S.data.tasks.length}</strong><span class="muted">completed</span></div><div class="progress-track" style="margin-top:15px"><span style="width:${S.data.tasks.length?S.data.tasks.filter(completed).length/S.data.tasks.length*100:0}%"></span></div></div><div class="gentle-note">${icon('heart',19)} Small steps every day make a big difference.</div></aside></div>`}
function remindersPage(){let tasks=S.data.tasks.filter(t=>S.filter==='All'||t.type===S.filter);return `${head(T('reminders'),'A gentle nudge, right when you need it.',`<button class="btn" data-action="task-add">${icon('plus',17)} ${T('add')}</button>`)}<div class="tabs">${['All','Medicine','Water','Appointment','Meal'].map(f=>`<button class="tab ${S.filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="content-grid"><section class="card routine-list routine-manage">${routineRows(tasks,true)}</section><aside class="stack"><div class="card panel"><h2>A little extra support</h2><p class="muted">Allow browser notifications for reminders while this page is open.</p><button class="btn soft" data-action="notifications">${icon('bell',18)} Enable notifications</button></div><div class="gentle-note">If you are unsure whether you took medicine, check with your caregiver before another dose.</div></aside></div>`}
function gameName(type){return MM_GAMES.types.find(x=>x[0]===type)?.[1]||T('games')}
function gamesPage(){if(S.game)return gamePlay();if(S.gameType)return `${head(gameName(S.gameType),'Twelve little adventures. Choose a place to begin.',`<button class="btn secondary" data-action="all-games">${icon('back',17)} ${T('games')}</button>`)}<div class="level-grid">${MM_GAMES.themes.map((theme,i)=>{let done=S.data.gameResults.some(g=>g.type===S.gameType&&g.level===i+1);return `<button class="level-card" data-level="${i+1}"><span class="level-number">${T('level')} ${String(i+1).padStart(2,'0')}</span><div class="level-art art-emoji">${theme[2].slice(0,3).join(' ')}</div><h3>${theme[0]}</h3><small>${done?'✓ Completed · play again':i<4?'Easy · take your time':i<8?'A little more discovery':'A gentle challenge'}</small></button>`}).join('')}</div>`;return `${head(T('games'),'A little play. A little discovery. All at your own pace.')}<div class="banner">${icon('star',17)} Six activities · 12 unique levels in each · ${S.data.gameResults.length} activities completed</div><div class="game-grid">${MM_GAMES.types.map(([key,title,desc])=>{let index=MM_GAMES.types.findIndex(t=>t[0]===key),theme=MM_GAMES.themes[index],count=new Set(S.data.gameResults.filter(r=>r.type===key).map(r=>r.level)).size;return `<article class="card game-card"><div class="game-card-art" style="background:${theme[1]}"><span class="art-emoji">${theme[2][0]}</span><span class="art-emoji">${theme[2][2]}</span></div><div class="game-card-body"><h3>${title}</h3><p>${desc}</p><div class="between"><span class="tag">12 levels</span><small>${count}/12 explored</small></div><button class="btn soft" data-game="${key}">${T('play')} ${icon('arrow',16)}</button></div></article>`}).join('')}</div>`}
function gamePlay(){let g=S.game;if(g.finished)return `<section class="card completed-card"><div class="trophy">🌟</div><span class="tag">${g.theme[0]}</span><h2>A lovely moment of progress!</h2><p>${gameName(g.type)} · ${T('level')} ${g.level}<br>You took your time and gave it a try. That matters.</p><div class="stats-grid" style="grid-template-columns:1fr 1fr"><div><strong style="font-size:1.8rem">${MM_GAMES.result(g).score}</strong><small style="display:block">Activity score</small></div><div><strong style="font-size:1.8rem">${g.moves}</strong><small style="display:block">Thoughtful tries</small></div></div><div class="flex" style="justify-content:center;flex-wrap:wrap"><button class="btn secondary" data-action="game-replay">${T('again')}</button>${g.level<12?`<button class="btn" data-action="game-next">${T('next')} ${T('level')} ${icon('arrow',17)}</button>`:`<button class="btn" data-action="game-levels">Choose another activity</button>`}</div><button class="link-btn" data-action="game-levels" style="margin-top:18px">Back to levels</button></section>`;return `${head(gameName(g.type),g.theme[0],`<button class="btn secondary" data-action="game-levels">${icon('back',17)} Levels</button>`)}<div class="game-stage"><section class="game-instruction" style="background:${g.theme[1]};color:#153e5b"><div><h2 style="color:#082e56">${g.type==='match'?'Find the matching pairs':E(g.question)}</h2><p>${g.type==='match'?'Tap two cards. Remember the pictures, then find their friends.':g.type==='word'&&g.revealed?'Read the word. When you are ready, hide it.':'Choose an answer below. There is no time limit.'}</p></div><div class="level-token">${icon('brain',28)}${T('level')} ${g.level}<br>${g.level<5?'Easy':'Explore'}</div></section>${g.type==='match'?`<div class="match-grid">${g.cards.map(c=>{let show=g.selected.includes(c.id)||g.matched.includes(c.art);return `<button class="match-card ${show?'flipped':''} ${g.matched.includes(c.art)?'matched':''}" data-card="${c.id}" aria-label="${show?c.art:'Hidden picture '+(c.id+1)}" ${g.matched.includes(c.art)?'disabled':''}>${show?`<span class="art-emoji">${c.art}</span>`:icon('brain',55)}</button>`}).join('')}</div>`:`<section class="card game-question">${g.type==='word'?`<div class="question-art">${g.revealed?`<strong>${E(g.target)}</strong>`:'💭'}</div>${g.revealed?`<button class="btn" data-action="hide-word">I’m ready — hide the word</button>`:'<h2>Which word did you see?</h2>'}`:g.type==='number'?`<div class="question-art">${g.sequence.map(n=>`<span class="sequence-item">${n}</span>`).join('')}<span class="sequence-item blank">?</span></div>`:g.target?`<div class="question-art art-emoji">${E(g.target)}</div>`:`<div class="question-art art-emoji">${g.theme[2][0]}</div>`}${g.type==='word'&&g.revealed?'':`<div class="choice-grid">${g.choices.map((c,i)=>`<button class="choice-btn" data-answer="${i}">${g.type==='word'||g.type==='number'?E(c):`<span class="art-emoji">${E(c)}</span>`}</button>`).join('')}</div>`}</section>`}<div class="game-feedback" role="status">${E(g.feedback||T('takeTime'))}</div><div class="game-scorebar"><span>${icon('star',19)} ${T('score')}: <strong>${g.correct*20}</strong></span><span>${icon('clock',18)} <span id="game-timer">00:00</span></span></div></div>`}
function memoriesPage(){let list=S.filter==='All'?S.data.memories:S.data.memories.filter(m=>m.category===S.filter);return `${head(T('memories'),'Your people. Your stories. Your happy moments.',`<button class="btn" data-action="memory-add">${icon('plus',17)} ${T('add')}</button>`)}<div class="tabs">${['All','Family','Photos','Places','Favorites','Important Dates','Personal Stories'].map(x=>`<button class="tab ${S.filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="memory-grid">${list.map(m=>`<article class="card memory-card"><div class="memory-art" ${m.photo?'':`style="background:${m.category==='Places'?'#e2f0f6':m.category==='Favorites'?'#eee7fa':'#e7f3e8'}"`}>${m.photo?`<img src="${m.photo}" alt="${E(m.title)}">`:`<span class="art-emoji">${E(m.art||'📷')}</span>`}</div><div class="memory-body"><span class="tag">${E(m.category)}</span><h3>${E(m.title)}</h3><p>${E(m.description)}</p><small>${E(m.date||'A special memory')}</small><div class="memory-controls"><button class="btn soft small" data-action="memory-speak" data-id="${m.id}">${icon('volume',16)} ${T('listen')}</button><button class="mini-action" data-action="memory-edit" data-id="${m.id}" aria-label="Edit memory">${icon('edit',15)}</button><button class="mini-action" data-action="memory-delete" data-id="${m.id}" aria-label="Delete memory">${icon('trash',15)}</button></div></div></article>`).join('')||'<div class="card empty">No memories in this category. Add a moment to keep.</div>'}</div>`}
function chatPage(){return `${head(T('talk'),'A familiar voice. A little company. Whenever you need it.',`<button class="btn outline-red" data-nav="help">${icon('shield',18)} ${T('help')}</button>`)}<div class="chat-layout"><section class="card chat-panel"><div class="chat-header"><img src="public/assets/avatar.png" alt="" width="43" height="49"><div><strong>Manas-Mitra</strong><small>${cloudHealth()?.ai?'AI companion · AI-generated voice':'Gentle companion · demo replies'}</small></div></div><div class="chat-log" id="chat-log" aria-live="polite">${(S.data.conversations.length?S.data.conversations:[{role:'assistant',text:`${T('greeting')}, ${S.data.profile.name}. ${T('askMe')}`,at:Date.now()}]).map((m,i)=>`<div class="message ${m.role==='user'?'user':''}"><div class="bubble"><p>${E(m.text)}</p></div><small>${m.role==='user'?E(S.data.profile.name):'Manas-Mitra'} · ${timeStamp(m.at)}</small>${m.role==='assistant'?`<div class="message-tools"><button data-action="message-speak" data-id="${i}">${icon('volume',13)} ${T('listen')}</button><button data-action="message-copy" data-id="${i}">Copy</button><button data-action="remember-message" data-id="${i}">Save as memory</button></div>`:''}</div>`).join('')}${S.chatBusy?'<div class="message"><div class="bubble">Let me think…</div></div>':''}</div><form class="chat-form" id="chat-form"><label for="chat-text" class="sr-only">Your message</label><textarea id="chat-text" name="text" rows="1" placeholder="${E(T('askMe'))}" maxlength="2000" required></textarea><button class="btn" type="submit" ${S.chatBusy?'disabled':''}>${T('send')}</button></form></section><aside class="stack chat-side"><section class="card voice-panel"><img src="public/assets/avatar.png" alt="Your companion" width="150" height="140"><h2>We can talk together</h2><p>Tap to speak. Tap again when you’re finished.</p><button class="mic ${S.voice==='listening'?'listening':''}" data-action="microphone" aria-label="${S.voice==='listening'?'Stop recording':'Start voice conversation'}">${icon(S.voice==='listening'?'stop':'mic',35)}</button><div class="voice-status" id="voice-status" role="status">${voiceStatusText()}</div><button class="link-btn" data-action="stop-voice">Stop speaking</button></section><div class="suggestions">${['What do I have to do today?','Did I take my medicine?','Tell me about my family.'].map(q=>`<button data-prompt="${E(q)}">${q}</button>`).join('')}</div><div class="banner" style="margin:0;font-size:.76rem">${voiceAvailabilityText()}</div></aside></div>`}
function voiceStatusText(){return {idle:'I’m here when you’re ready.',listening:'I’m listening…',transcribing:'Let me hear that…',processing:'Let me think…',speaking:'Manas-Mitra is speaking…'}[S.voice]||'Ready'}
function cloudHealth(){let h=S.health;if(!h)return null;if(h.authMode!=='workspace'&&!S.user&&!h.demoAIAllowed)return {...h,ai:false,voice:false,transcription:false};return h}
function voiceAvailabilityText(){let code=S.data.settings.language,h=cloudHealth(),name=lang().name,device=MM_VOICE.installedVoice(lang().code);let speak=h?.ttsLanguages?.includes(code)&&h.voice?'Cloud speech configured':device?'Device voice available':'No supported speaking voice';let listen=h?.sttLanguages?.includes(code)&&h.transcription?'Cloud listening configured':'Browser listening depends on device support';return `${E(name)}: ${speak}. ${listen}. ${S.health?.requiresSignIn&&!S.user?'Sign in to use cloud AI and speech. ':''}${!S.health?.ai?'Full conversation needs a configured AI server. ':''}Provider availability is checked when used. AI-generated voice; review the transcript before sending.`}
function chart(){let list=S.data.gameResults.slice(-7);if(!list.length)return '<div class="empty">Your activity trend will appear after a few games.</div>';let pts=list.map((r,i)=>`${45+i*(500/Math.max(1,list.length-1))},${165-r.score*1.3}`);return `<svg class="chart" viewBox="0 0 590 200" role="img" aria-label="Game activity score trend"><title>Activity scores from completed games, not a clinical assessment</title>${[25,50,75,100].map(y=>`<line x1="45" x2="560" y1="${165-y*1.3}" y2="${165-y*1.3}"/><text x="10" y="${169-y*1.3}">${y}</text>`).join('')}<polyline points="${pts.join(' ')}"/>${list.map((r,i)=>`<circle cx="${45+i*(500/Math.max(1,list.length-1))}" cy="${165-r.score*1.3}" r="4"/><text x="${35+i*(500/Math.max(1,list.length-1))}" y="190">${new Date(r.at).toLocaleDateString('en',{day:'numeric',month:'short'})}</text>`).join('')}</svg>`}
function stats(){let results=S.data.gameResults,avg=results.length?Math.round(results.reduce((a,b)=>a+b.score,0)/results.length):null,done=S.data.tasks.filter(completed).length;return `<div class="stats-grid">${[['Activity score',avg===null?'—':avg+' <small>/ 100</small>','From completed games'],['Games played',results.length,'At their own pace'],['Routine progress',S.data.tasks.length?Math.round(done/S.data.tasks.length*100)+'%':'—',`${done}/${S.data.tasks.length} tasks marked complete`],['Today’s mood',S.data.mood?({good:'😊 Good',okay:'😌 Okay',low:'😔 Low'})[S.data.mood]:'—','Reported by the patient']].map(([label,value,foot])=>`<section class="card stat-card"><div class="stat-title">${label}</div><span class="stat-value">${value}</span><span class="stat-foot">${foot}</span></section>`).join('')}</div>`}
function careHome(){return `${head(S.role==='doctor'?'Care overview':'Patient overview',S.role==='doctor'?'A clear view of daily activities and your care notes.':'A little reassurance. A shared understanding.')}<section class="card greeting-card">${avatar()}<div><h1>${E(S.data.profile.name)}</h1><p>Age ${S.data.profile.age} · ${E(S.data.profile.city)}</p></div><div class="date"><span class="tag">${S.user?'Linked care circle':'Fictional demo patient'}</span><button class="link-btn" data-nav="patient" style="display:block;margin-left:auto">View profile ${icon('arrow',15)}</button></div></section>${stats()}<div class="content-grid"><section class="stack"><div class="card chart-card"><div class="section-head"><h2>Activity progress</h2><button class="link-btn" data-nav="progress">View details ${icon('arrow',15)}</button></div>${chart()}<p class="chart-caption">Game scores reflect activity performance. They are not a medical assessment.</p></div><div class="card"><div class="panel" style="padding-bottom:0"><h2>${S.role==='doctor'?'Care notes':'Recent activity'}</h2></div>${S.role==='doctor'?notesList(3):recentList()}</div></section><aside class="stack"><div class="card routine-list"><div class="section-head" style="padding-top:22px"><h2>Today’s routine</h2><button class="link-btn" data-nav="reminders">Manage</button></div>${routineRows(S.data.tasks.slice(0,4))}</div><div class="card panel"><h2>Stay connected</h2><p class="muted">Share a note with the care circle or arrange the next check-in.</p><div class="stack"><button class="btn soft" data-nav="messages">${icon('mail',18)} Open messages</button><button class="btn secondary" data-nav="appointments">${icon('calendar',18)} Appointments</button></div></div></aside></div>`}
function recentList(){let items=[...S.data.gameResults.map(g=>({at:g.at,title:`Completed ${gameName(g.type)}`,sub:`Level ${g.level} · Score ${g.score}`,icon:'brain'})),...S.data.tasks.filter(completed).map(t=>({at:t.completedAt,title:taskTitle(t),sub:'Marked complete',icon:t.icon}))].sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,5);return items.length?`<div class="routine-list">${items.map(x=>`<div class="routine-item"><span class="routine-symbol">${icon(x.icon,22)}</span><div class="routine-copy"><strong>${E(x.title)}</strong><small>${timeStamp(x.at)} · ${E(x.sub)}</small></div>${icon('arrow',15)}</div>`).join('')}</div>`:'<div class="empty">Activity will appear as your day unfolds.</div>'}
function progressPage(){let results=S.data.gameResults;return `${head(T('progress'),'Small steps are worth noticing.')}${stats()}<div class="card chart-card"><h2>Activity score trend</h2>${chart()}<p class="chart-caption">This is a record of game activity, not a cognitive diagnosis.</p></div><div class="content-grid" style="margin-top:21px"><section class="card panel"><h2>Games explored</h2>${MM_GAMES.types.map(([key,title])=>{let count=new Set(results.filter(r=>r.type===key).map(r=>r.level)).size;return `<div class="progress-row"><div class="between"><span>${title}</span><strong>${count}/12</strong></div><div class="progress-track"><span style="width:${count/12*100}%"></span></div></div>`}).join('')}</section><section class="card panel"><h2>Your recent games</h2>${results.slice(-5).reverse().map(r=>`<div class="routine-item"><div class="routine-copy"><strong>${gameName(r.type)} · ${T('level')} ${r.level}</strong><small>${new Date(r.at).toLocaleDateString()} · ${r.seconds}s · ${r.incorrect} extra tries</small></div><span class="tag">${r.score}</span></div>`).join('')||'<p class="muted">No completed games yet.</p>'}<button class="btn secondary small" data-action="export-progress" style="margin-top:17px">Download progress CSV</button></section></div>`}
function patientDetails(){let p=S.data.profile;return `${head(T('patient')+' profile','The little things that help us care well.',`<button class="btn" data-action="profile-edit">${icon('edit',17)} ${T('edit')}</button>`)}<div class="content-grid"><section class="card panel"><div class="flex">${avatar('large')}<div><h2 style="margin:0 0 6px">${E(p.name)}</h2><p class="muted" style="margin:0">Age ${p.age} · ${E(p.city)}</p></div></div><div class="setting-line" style="margin-top:24px"><strong>Preferred language</strong><span>${lang().label}</span></div><div class="setting-line"><strong>Caregiver</strong><span>${E(p.caregiver)}</span></div><div class="setting-line"><strong>Doctor</strong><span>${E(p.doctor)}</span></div><div class="setting-line"><strong>Favorite activities</strong><span>Music, gardens, family</span></div>${S.user&&S.user.role==='patient'?`<h3 style="margin-top:22px">Invite your care circle</h3><p class="muted">Share this code privately with your caregiver or doctor. You control who joins.</p><div class="code">${E(S.user.careCode||'')}</div>`:''}</section><aside class="stack"><div class="card panel"><h2>People & places</h2>${S.data.memories.slice(0,3).map(m=>`<div class="routine-item"><span class="art-emoji" style="font-size:1.7rem">${m.art||'📷'}</span><div class="routine-copy"><strong>${E(m.title)}</strong><small>${E(m.category)}</small></div></div>`).join('')}<button class="link-btn" data-nav="memories">Open memories ${icon('arrow',15)}</button></div></aside></div>`}
function notesList(limit=100){let list=S.data.notes.slice().reverse().slice(0,limit);return list.length?list.map(n=>`<article class="note"><div class="between"><strong>${E(n.title)}</strong><span class="tag blue">${E(n.author)}</span></div><p>${E(n.body)}</p><small>${new Date(n.at).toLocaleString()}</small></article>`).join(''):'<div class="empty">No care notes yet. Notes added by the doctor appear here.</div>'}
function notesPage(){return `${head(T('notes'),'Observations and plans from the care team.',S.role==='doctor'?`<button class="btn" data-action="note-add">${icon('plus',17)} Add note</button>`:'')}<div class="card">${notesList()}</div>`}
function appointmentsPage(){return `${head(T('appointments'),'A clear plan for your next check-in.',`<button class="btn" data-action="appointment-add">${icon('plus',17)} ${T('add')}</button>`)}<div class="card">${S.data.appointments.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(a=>`<article class="appointment"><div class="date-box"><strong>${new Date(a.date+'T12:00:00').getDate()}</strong><small>${new Date(a.date+'T12:00:00').toLocaleDateString('en',{month:'short'})}</small></div><div><h3>${E(a.title)}</h3><p>${timeLabel(a.time)} · ${E(a.location)} · ${E(a.status||'Scheduled')}</p></div><button class="mini-action" data-action="appointment-delete" data-id="${a.id}" aria-label="Cancel appointment">${icon('trash',16)}</button></article>`).join('')||'<div class="empty">No appointments yet. Add your next visit or call.</div>'}</div>`}
function messagesPage(){return `${head(T('messages'),'A shared conversation with your care circle.')}<div class="card chat-panel" style="min-height:420px"><div class="chat-log" id="chat-log">${S.data.careMessages.map(m=>`<div class="message ${m.role===S.role?'user':''}"><div class="bubble"><p>${E(m.text)}</p></div><small>${E(m.author)} · ${timeStamp(m.at)}</small></div>`).join('')||'<div class="empty">A simple hello can mean a lot. Start a conversation here.</div>'}</div><form class="chat-form" id="care-message-form"><label class="sr-only" for="care-message">Message</label><textarea id="care-message" name="text" rows="1" required maxlength="2000" placeholder="Write a message to your care circle…"></textarea><button class="btn" type="submit">${T('send')}</button></form></div><p class="muted" style="font-size:.8rem;margin-top:15px">${S.user?'Messages are saved to your linked care circle.':'Demo messages stay on this device. Sign in to share with linked accounts.'} This is not an emergency service.</p>`}
function musicPage(){return `${head(T('music'),'A quiet moment, just for you.')}<div class="music-grid">${[['rain','🌧️','Soft rain','A gentle wash of rain-like sound.'],['calm','🎵','Calm tones','Soft, slow tones for a peaceful pause.'],['breathe','🌿','Breathing space','Follow a gentle four-second breathing rhythm.']].map(([k,art,title,desc])=>`<section class="card music-card"><span class="music-symbol art-emoji">${art}</span><h2>${title}</h2><p>${desc}</p><button class="btn soft" data-action="music" data-id="${k}">${S.music===k?'Stop':'Play'} ${icon(S.music===k?'stop':'music',17)}</button></section>`).join('')}</div><div class="gentle-note" style="margin-top:22px">Use a comfortable volume. Stop whenever you wish.</div>`}
function helpPage(){return `${head(T('help'),'You are not alone. Someone can help.')}<section class="emergency-stage"><div class="emergency-heading">${icon('shield',35)}<div><h2>Need help?</h2><p>Tap SOS to choose and confirm a phone call.</p></div></div><div class="sos-wrap"><button class="sos" data-action="emergency">${icon('phone',42)}SOS</button><strong>Emergency call</strong><div class="muted" style="font-size:.82rem">We will ask before opening your phone app.</div></div><div class="card">${[['caregiver',S.data.profile.caregiver,S.data.profile.phone],['doctor',S.data.profile.doctor,S.data.profile.doctorPhone],['emergency','Emergency service',S.data.profile.emergencyPhone]].map(([k,n,p])=>`<div class="contact-row"><span class="routine-symbol">${icon('phone',20)}</span><div><strong>${E(n)}</strong><small>${p?E(p):'Add a phone number in settings'}</small></div><button class="icon-btn" data-call="${k}" aria-label="Call ${E(n)}" ${p?'':'disabled'}>${icon('phone',19)}</button></div>`).join('')}</div><button class="link-btn" data-nav="settings" style="margin-top:17px">Manage emergency contacts ${icon('arrow',15)}</button></section>`}
function settingsPage(){let s=S.data.settings,p=S.data.profile;return `${head(T('settings'),'Make this space comfortable for you.')}<div class="settings-grid"><section class="card settings-card"><h2>${T('patient')} & care circle</h2><div class="flex" style="margin-bottom:20px">${avatar()}<div><strong>${E(p.name)}</strong><small style="display:block">${E(p.city)} · ${p.age} years</small></div></div><button class="btn secondary small" data-action="profile-edit">Edit profile & contacts</button><div class="setting-line" style="margin-top:19px"><div><strong>Account</strong><small>${S.user?E(S.user.email):'You are exploring a fictional demo.'}</small></div><button class="btn soft small" data-action="${S.user?'logout':'signin'}">${S.user?'Sign out':'Sign in'}</button></div>${S.user?.careCode?`<div class="setting-line"><strong>Care circle code</strong><span class="code">${E(S.user.careCode)}</span></div>`:''}</section><section class="card settings-card"><h2>${T('language')} & voice</h2><button class="btn secondary small" data-action="voice-test">${T('listen')} · Test selected language</button><div class="setting-line"><label>Preferred language</label>${languageSelect()}</div><div class="setting-line"><label for="speed">Speaking speed</label><select id="speed" data-setting="speed"><option value="0.8" ${s.speed==.8?'selected':''}>Slow</option><option value="0.9" ${s.speed==.9?'selected':''}>Gentle</option><option value="1" ${s.speed==1?'selected':''}>Normal</option></select></div><div class="setting-line"><label for="voice">AI voice</label><select id="voice" data-setting="voice">${['coral','sage','alloy','ash'].map(v=>`<option ${s.voice===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="setting-line"><label for="volume">Volume</label><input type="range" min="0" max="1" step=".05" id="volume" data-setting="volume" value="${s.volume}"></div><div class="setting-line"><label for="autoSpeak">Speak replies aloud</label><input id="autoSpeak" type="checkbox" data-setting="autoSpeak" ${s.autoSpeak?'checked':''}></div><p class="muted" style="font-size:.76rem;margin:12px 0 0">${voiceAvailabilityText()}</p></section><section class="card settings-card"><h2>Appearance & accessibility</h2><div class="setting-line"><label for="theme">Appearance</label><select id="theme" data-setting="theme">${['light','dark','system'].map(x=>`<option value="${x}" ${s.theme===x?'selected':''}>${x.charAt(0).toUpperCase()+x.slice(1)}</option>`).join('')}</select></div><div class="setting-line"><label for="font">Size of the interface</label><select id="font" data-setting="font">${[['small','Small'],['medium','Medium'],['large','Large'],['xlarge','Extra large']].map(([k,l])=>`<option value="${k}" ${s.font===k?'selected':''}>${l}</option>`).join('')}</select></div>${[['contrast','High contrast'],['reducedMotion','Reduced motion'],['largeTargets','Larger touch targets']].map(([k,l])=>`<div class="setting-line"><label for="${k}">${l}</label><input id="${k}" type="checkbox" data-setting="${k}" ${s[k]?'checked':''}></div>`).join('')}</section><section class="card settings-card"><h2>Notifications & privacy</h2><p class="muted" style="font-size:.88rem">${S.user?'Account information is saved by your server and shared with your linked care circle.':'Demo information is stored only in this browser. Anyone using this browser profile can see it.'}</p><div class="stack"><button class="btn secondary small" data-action="notifications">Enable browser reminders</button><button class="btn secondary small" data-action="clear-chat">Clear companion conversation</button><button class="btn outline-red small" data-action="clear-memories">Delete saved memories</button></div></section></div><section class="card panel" style="margin-top:21px"><div class="between"><div><h2 style="margin-bottom:8px">Your connection</h2><p class="muted" style="margin:0;font-size:.86rem">${S.health?'Server available':'Device demo'} · ${S.health?.ai?'AI connected':'AI connection not configured'} · ${navigator.onLine?'Online':'Offline'}</p></div><button class="btn outline-red small" data-nav="help">${icon('shield',17)} Emergency contacts</button></div></section>`}
function morePage(){return `${head(T('more'),'Everything you need, in one place.')}<div class="activity-grid">${[['memories','image'],['talk','mic'],['music','music'],['settings','settings'],['help','phone'],['appointments','calendar'],['messages','mail']].map(([v,i],n)=>`<button class="activity-tile ${['tile-sky','tile-green','tile-purple','tile-blue','tile-peach','tile-yellow'][n%6]}" data-nav="${v}"><span class="activity-icon">${icon(i,42)}</span><strong>${T(v)}</strong></button>`).join('')}</div>`}
function openDialog(title,html){$('#dialog').innerHTML=`<div class="dialog-inner"><button class="dialog-close" data-action="close-dialog" aria-label="Close">${icon('close',18)}</button><h2 id="dialog-title">${E(title)}</h2>${html}</div>`;$('#dialog').showModal()}
function closeDialog(){$('#dialog').close()}
function confirmDialog(title,text,action,id){openDialog(title,`<p>${E(text)}</p><div class="form-actions"><button class="btn secondary" data-action="close-dialog">${T('cancel')}</button><button class="btn ${action.includes('delete')||action.includes('clear')?'red':''}" data-action="${action}" data-id="${id||''}">Confirm</button></div>`)}
function taskDialog(task){let t=task||{title:'',time:'09:00',type:'Medicine',repeat:'Daily',priority:'Normal',active:true};openDialog(task?'Edit reminder':'Add a gentle reminder',`<form id="task-form"><input type="hidden" name="id" value="${task?.id||''}"><div class="form-row"><label for="task-title">Title</label><input id="task-title" name="title" maxlength="100" value="${E(taskTitle(t))}" required></div><div class="form-grid"><div class="form-row"><label for="task-time">Time</label><input id="task-time" type="time" name="time" value="${t.time}" required></div><div class="form-row"><label for="task-type">Type</label><select id="task-type" name="type">${['Medicine','Meal','Water','Activity','Exercise','Family','Appointment','Sleep'].map(v=>`<option ${t.type===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="form-grid"><div class="form-row"><label for="task-repeat">Repeat</label><select id="task-repeat" name="repeat">${['Daily','Weekly','Once'].map(v=>`<option ${t.repeat===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-row"><label for="task-priority">Priority</label><select id="task-priority" name="priority">${['Normal','High'].map(v=>`<option ${t.priority===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="setting-line"><label for="task-active">Reminder active</label><input id="task-active" type="checkbox" name="active" ${t.active?'checked':''}></div><div class="form-actions">${task?`<button type="button" class="btn outline-red" data-action="task-delete" data-id="${task.id}">${T('delete')}</button>`:''}<button type="button" class="btn secondary" data-action="close-dialog">${T('cancel')}</button><button class="btn" type="submit">${T('save')}</button></div></form>`)}
function memoryDialog(memory){let m=memory||{title:'',description:'',category:'Family',date:'',art:'📷'};openDialog(memory?'Edit your memory':'Save a special moment',`<form id="memory-form"><input type="hidden" name="id" value="${m.id||''}"><div class="form-row"><label for="memory-title">Title</label><input id="memory-title" name="title" value="${E(m.title)}" required maxlength="100"></div><div class="form-row"><label for="memory-desc">Your story</label><textarea id="memory-desc" name="description" required maxlength="1500">${E(m.description)}</textarea></div><div class="form-grid"><div class="form-row"><label for="memory-category">Category</label><select id="memory-category" name="category">${['Family','Photos','Places','Favorites','Important Dates','Personal Stories'].map(v=>`<option ${v===m.category?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-row"><label for="memory-date">Date or occasion</label><input id="memory-date" name="date" value="${E(m.date)}" maxlength="60"></div></div><div class="form-row"><label for="memory-photo">Photo (optional, up to 1 MB)</label><input id="memory-photo" type="file" accept="image/png,image/jpeg,image/webp" name="photo"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close-dialog">${T('cancel')}</button><button class="btn" type="submit">${T('save')}</button></div></form>`)}
function profileDialog(){let p=S.data.profile;openDialog('Profile & emergency contacts',`<form id="profile-form"><div class="form-grid">${[['name','Preferred name','text'],['age','Age','number'],['city','City','text'],['caregiver','Caregiver name','text'],['doctor','Doctor name','text'],['phone','Caregiver phone','tel'],['doctorPhone','Doctor phone','tel'],['emergencyPhone','Emergency service number','tel']].map(([k,l,type])=>`<div class="form-row"><label for="profile-${k}">${l}</label><input id="profile-${k}" name="${k}" type="${type}" value="${E(p[k]||'')}" maxlength="80" ${type==='number'?'min="1" max="120"':''} ${['name','age'].includes(k)?'required':''}></div>`).join('')}</div><div class="form-actions"><button type="button" class="btn secondary" data-action="close-dialog">${T('cancel')}</button><button class="btn" type="submit">${T('save')}</button></div></form>`)}
function emergencyDialog(contact){let p=S.data.profile;let entries=[['caregiver',p.caregiver,p.phone],['doctor',p.doctor,p.doctorPhone],['emergency','Emergency service',p.emergencyPhone]].filter(x=>!contact||x[0]===contact);openDialog('Do you need emergency help?',`<p>The button below opens your device’s phone app. It does not send a message or share your location.</p><div class="modal-actions">${entries.map(([k,n,num])=>num?`<a class="btn red large" href="tel:${E(num.replace(/[^+\d]/g,''))}" data-action="call-opened">${icon('phone',20)} Call ${E(n)} · ${E(num)}</a>`:`<div class="banner warning">No number saved for ${E(n)}.</div>`).join('')}<button class="btn secondary" data-action="close-dialog">${T('cancel')}</button><button class="link-btn" data-action="contacts-settings">Manage phone numbers</button></div>`)}
function authDialog(mode='login',role=S.role||'patient'){let register=mode==='register',workspace=S.health?.authMode==='workspace';openDialog(register?'Create your care account':'Welcome back',`<p>Sign in to share your care circle’s information across devices.</p><form id="auth-form"><input type="hidden" name="mode" value="${mode}">${register?`<div class="form-row"><label for="auth-name">Your name</label><input id="auth-name" name="name" required maxlength="80"></div><div class="form-row"><label for="auth-role">Your role</label><select id="auth-role" name="role">${['patient','caregiver','doctor'].map(v=>`<option value="${v}" ${role===v?'selected':''}>${T(v)}</option>`).join('')}</select></div>`:''}${workspace?'<div class="banner">Your signed-in ChatGPT account securely identifies you. No extra password is needed.</div>':`<div class="form-row"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" required maxlength="150"></div><div class="form-row"><label for="auth-password">Password</label><input id="auth-password" type="password" name="password" required minlength="10" autocomplete="${register?'new-password':'current-password'}"></div>`}${register?'<div class="form-row"><label for="auth-code">Care circle code (caregiver / doctor only)</label><input id="auth-code" name="careCode" maxlength="30" placeholder="The patient shares this code with you"></div>':''}<div class="validation-message" id="auth-error" role="alert"></div><button class="btn full" type="submit">${register?'Create account':'Sign in'}</button></form><button class="link-btn" data-action="${register?'signin':'signup'}" style="margin-top:15px">${register?'Already have an account? Sign in':'New here? Create an account'}</button><p class="muted" style="font-size:.76rem;margin:12px 0 0">${workspace?'Your care profile is saved securely online.':'Account services are provided by the local Node server.'} You can always explore the demo.</p>`)}
function completeTask(t){t.status='done';t.completionDate=dateKey();t.completedAt=Date.now();t.snoozedUntil=null;persist();render();toast('Marked complete. Thank you.')}
function finishGame(){let g=S.game;if(!g||!g.finished||g.saved)return;g.saved=true;S.data.gameResults.push(MM_GAMES.result(g));persist();render()}
function startGame(type,level){S.gameType=type;let recent=S.data.gameResults.filter(r=>r.type===type).slice(-3),gentle=recent.length===3&&recent.reduce((a,b)=>a+b.incorrect,0)>8;S.game=MM_GAMES.create(type,level,S.data.settings.language,gentle?'gentle':'adaptive');render()}
function flipCard(id){let g=S.game;if(!g||g.type!=='match'||g.lock||g.selected.includes(id)||g.finished)return;let c=g.cards.find(c=>c.id===id);if(!c||g.matched.includes(c.art))return;g.selected.push(id);if(g.selected.length===2){g.moves++;let [a,b]=g.selected.map(id=>g.cards.find(c=>c.id===id));if(a.art===b.art){g.matched.push(a.art);g.correct++;g.selected=[];g.feedback='Lovely — you found a pair!';if(g.matched.length===g.pairs){g.finished=true;finishGame();return}}else{g.incorrect++;g.lock=true;g.feedback='Keep those pictures in mind. Let’s look for their partners.';setTimeout(()=>{if(S.game===g){g.selected=[];g.lock=false;render()}},1100)}}render()}
async function sendChat(text){text=String(text||'').trim();if(!text||S.chatBusy)return;const language=S.data.settings.language;S.data.conversations.push({role:'user',text,language,at:Date.now()});S.chatBusy=true;S.voice='processing';render();let reply;try{if(!cloudHealth()?.ai)throw Error('demo');let response=await request('/ai/chat',{method:'POST',body:{message:text,language,context:{patient:S.data.profile,tasks:S.data.tasks.map(t=>({...t,title:taskTitle(t),status:completed(t)?'done':'pending'})),memories:S.data.memories.map(({photo,...m})=>m),recentMessages:S.data.conversations.slice(0,-1).filter(m=>!m.language||m.language===language).slice(-10)}}});reply=response.reply}catch(e){reply=demoReply(text,language);if(S.health?.ai)toast('The AI connection is unavailable. I can still help with the daily plan.')}S.data.conversations.push({role:'assistant',text:reply,language,at:Date.now()});S.chatBusy=false;S.voice='idle';persist();render();if(S.data.settings.autoSpeak&&S.data.settings.language===language)MM_VOICE.speak(reply,language)}
function demoReply(text,code=S.data.settings.language){let name=S.data.profile.name,questions={en:`I’m here with you, ${name}. Would you like to look at your day or a favorite memory?`,hi:`मैं आपके साथ हूँ, ${name}। क्या आप आज की योजना या कोई पसंदीदा याद देखना चाहेंगे?`,as:`মই আপোনাৰ লগত আছোঁ, ${name}। আজিৰ পৰিকল্পনা বা এটা প্ৰিয় স্মৃতি চাব বিচাৰিবনে?`,bn:`আমি আপনার পাশে আছি, ${name}। আজকের পরিকল্পনা বা প্রিয় স্মৃতি দেখতে চান?`,gu:`હું તમારી સાથે છું, ${name}. આજનો કાર્યક્રમ કે કોઈ પ્રિય યાદ જોવા માંગો છો?`,mr:`मी तुमच्यासोबत आहे, ${name}. आजची योजना किंवा एखादी आवडती आठवण पाहायची आहे का?`,ta:`நான் உங்களுடன் இருக்கிறேன், ${name}. இன்றைய திட்டம் அல்லது ஒரு இனிய நினைவை பார்க்க விரும்புகிறீர்களா?`,te:`నేను మీతో ఉన్నాను, ${name}. ఈ రోజు ప్రణాళిక లేదా మంచి జ్ఞాపకాన్ని చూడాలనుకుంటున్నారా?`,kn:`ನಾನು ನಿಮ್ಮ ಜೊತೆಯಲ್ಲಿದ್ದೇನೆ, ${name}. ಇಂದಿನ ಯೋಜನೆ ಅಥವಾ ಪ್ರೀತಿಯ ನೆನಪನ್ನು ನೋಡಲು ಬಯಸುತ್ತೀರಾ?`,lus:`Ka awm ve reng che, ${name}. I ni tih tur emaw hriatrengna emaw i en duh em?`,kha:`Nga don hangne bad phi, ${name}. Phi kwah ban peit ia ka jingthmu jong ka sngi lane ka jingkynmaw?`,mni:`ঐহাক নঙগা লোয়নরি, ${name}। ঙসিগী থৌরম নত্রগা নিংশিংবা অমা য়েংবা পাম্বগে?`};if(code!=='en')return questions[code];let q=text.toLowerCase();if(/medicine|pill|dose/.test(q)){let meds=S.data.tasks.filter(t=>t.type==='Medicine'),done=meds.filter(completed);return done.length?`${done.map(t=>taskTitle(t)+' at '+timeStamp(t.completedAt)).join(', ')} is marked complete today. If you’re unsure, please check with ${S.data.profile.caregiver}.`:`I don’t have confirmation that you took your medicine today. Please check with ${S.data.profile.caregiver} before taking another dose.`}if(/today|plan|routine|next/.test(q)){let tasks=pendingTasks().slice(0,2);return tasks.length?'Your next plans are '+tasks.map(t=>taskTitle(t)+' at '+timeLabel(t.time)).join(' and ')+'. We can take them one at a time.':'Your plan is complete for today. Would you like to enjoy a little music?'}if(/family|daughter|priya/.test(q))return `Your caregiver is ${S.data.profile.caregiver}. ${S.data.memories.find(m=>m.category==='Family')?.description||'Would you like to open your family memories?'}`;if(/pain|sick|doctor|diagnos/.test(q))return `I can’t diagnose how you’re feeling. Please speak with ${S.data.profile.caregiver} or your doctor. If you need urgent help, tap Help / SOS.`;if(/yes|call/.test(q))return 'If you want to call someone, open Help / SOS and choose your contact. I will always ask before opening a call.';return questions.en}
function voiceTranscript(text){openDialog('Is this what you said?',`<p>You can correct the words before sending.</p><form id="transcript-form"><label class="sr-only" for="transcript">Recognized speech</label><textarea id="transcript" name="text" required maxlength="2000">${E(text)}</textarea><div class="form-actions"><button class="btn secondary" type="button" data-action="close-dialog">${T('cancel')}</button><button class="btn" type="submit">${T('send')}</button></div></form>`)}
let audioContext=null,audioNodes=[];function stopMusic(){for(let n of audioNodes){try{n.stop?.();n.disconnect?.()}catch{}}audioNodes=[];audioContext?.close().catch(()=>{});audioContext=null;S.music=null}
function playMusic(type){if(S.music===type){stopMusic();render();return}stopMusic();let AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast('Audio playback is not supported in this browser.');return}audioContext=new AC();audioContext.resume();S.music=type;let gain=audioContext.createGain();gain.gain.value=.035;gain.connect(audioContext.destination);audioNodes.push(gain);if(type==='rain'){let buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=buffer.getChannelData(0),last=0;for(let i=0;i<data.length;i++){last=(last+(Math.random()*2-1)*.02)/1.02;data[i]=last*3.5}let src=audioContext.createBufferSource();src.buffer=buffer;src.loop=true;src.connect(gain);src.start();audioNodes.push(src)}else{let osc=audioContext.createOscillator();osc.type='sine';osc.frequency.value=type==='breathe'?196:261.63;osc.connect(gain);osc.start();audioNodes.push(osc);let lfo=audioContext.createOscillator(),lg=audioContext.createGain();lfo.frequency.value=type==='breathe'?.125:.08;lg.gain.value=.018;lfo.connect(lg);lg.connect(gain.gain);lfo.start();audioNodes.push(lfo,lg)}render()}
function exportProgress(){let rows=[['game','level','score','seconds','incorrect','date'],...S.data.gameResults.map(r=>[r.type,r.level,r.score,r.seconds,r.incorrect,r.at])];let blob=new Blob([rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='manas-mitra-progress.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function act(action,id){let t=S.data.tasks.find(t=>t.id===Number(id)),m=S.data.memories.find(m=>m.id===Number(id));switch(action){case'close-dialog':closeDialog();break;case'menu':{let el=$('#sidebar');el.classList.add('open');let b=document.createElement('div');b.className='drawer-backdrop show';b.onclick=()=>{el.classList.remove('open');b.remove()};document.body.append(b);break}case'leave':MM_VOICE.stop();stopMusic();S.role=null;S.view='home';render();break;case'signin':authDialog();break;case'signup':authDialog('register');break;case'logout':request('/auth/logout',{method:'POST'}).catch(()=>{});S.user=null;S.data=readDemo();S.role=null;render();break;case'profile-edit':profileDialog();break;case'task-add':taskDialog();break;case'task-edit':if(t)taskDialog(t);break;case'task-delete':if(t){closeDialog();confirmDialog('Delete this reminder?',taskTitle(t),'task-delete-confirm',id)}break;case'task-delete-confirm':S.data.tasks=S.data.tasks.filter(t=>t.id!==Number(id));persist();closeDialog();render();break;case'task-done':if(t){if(completed(t)){t.status='pending';t.completionDate=null;persist();render()}else if(t.type==='Medicine')confirmDialog('Confirm medicine was taken','Mark this complete only if you know the medicine was taken. This does not tell you to take another dose.','medicine-confirm',id);else completeTask(t)}break;case'medicine-confirm':if(t){completeTask(t);closeDialog()}break;case'task-snooze':if(t)openDialog('Remind me a little later',`<p>${E(taskTitle(t))}</p><div class="modal-actions"><button class="btn soft" data-snooze="10" data-id="${id}">In 10 minutes</button><button class="btn soft" data-snooze="30" data-id="${id}">In 30 minutes</button><button class="btn secondary" data-action="close-dialog">${T('cancel')}</button></div>`);break;case'memory-add':memoryDialog();break;case'memory-edit':if(m)memoryDialog(m);break;case'memory-delete':if(m)confirmDialog('Delete this memory?',m.title,'memory-delete-confirm',id);break;case'memory-delete-confirm':S.data.memories=S.data.memories.filter(m=>m.id!==Number(id));persist();closeDialog();render();break;case'memory-speak':if(m)MM_VOICE.speak(m.description);break;case'all-games':S.gameType=null;S.game=null;render();break;case'game-levels':S.game=null;render();break;case'game-replay':startGame(S.game.type,S.game.level);break;case'game-next':startGame(S.game.type,S.game.level+1);break;case'hide-word':if(S.game){S.game.revealed=false;S.game.question='Which word did you see?';render()}break;case'mood':S.data.mood=id;persist();render();toast('Thank you for sharing how you feel.');break;case'emergency':emergencyDialog();break;case'call-opened':closeDialog();break;case'contacts-settings':closeDialog();go('settings');profileDialog();break;case'microphone':MM_VOICE.listen();break;case'voice-test':MM_VOICE.speak(`${T('greeting')}. ${T('askMe')}`);break;case'stop-voice':MM_VOICE.stop();break;case'message-speak':MM_VOICE.speak(S.data.conversations[id]?.text||`${T('greeting')}, ${S.data.profile.name}. ${T('askMe')}`,S.data.conversations[id]?.language);break;case'message-copy':navigator.clipboard?.writeText(S.data.conversations[id]?.text||'').then(()=>toast('Copied.')).catch(()=>toast('Copy is not available in this browser.'));break;case'remember-message':memoryDialog({title:'A conversation to remember',description:S.data.conversations[id]?.text||'',category:'Personal Stories',date:todayDate()});break;case'clear-chat':confirmDialog('Clear this conversation?','Your saved memories will remain.','clear-chat-confirm');break;case'clear-chat-confirm':S.data.conversations=[];persist();closeDialog();render();break;case'clear-memories':confirmDialog('Delete all saved memories?','This cannot be undone.','clear-memories-confirm');break;case'clear-memories-confirm':S.data.memories=[];persist();closeDialog();render();break;case'notifications':if(!('Notification'in window)){toast('This browser cannot show notifications.');break}Notification.requestPermission().then(p=>toast(p==='granted'?'Notifications enabled while this page is open.':'Notifications were not enabled.'));break;case'note-add':if(S.role==='doctor')openDialog('Add a care note',`<form id="note-form"><div class="form-row"><label for="note-title">Title</label><input id="note-title" name="title" required maxlength="100"></div><div class="form-row"><label for="note-body">Observation or plan</label><textarea id="note-body" name="body" required maxlength="4000"></textarea></div><button class="btn full" type="submit">Save care note</button></form>`);break;case'appointment-add':openDialog('Plan an appointment',`<form id="appointment-form"><div class="form-row"><label for="appointment-title">Visit or call</label><input id="appointment-title" name="title" required maxlength="100"></div><div class="form-grid"><div class="form-row"><label for="appointment-date">Date</label><input id="appointment-date" type="date" name="date" value="${todayDate()}" required></div><div class="form-row"><label for="appointment-time">Time</label><input id="appointment-time" type="time" name="time" value="10:00" required></div></div><div class="form-row"><label for="appointment-location">Place or contact</label><input id="appointment-location" name="location" maxlength="150" required></div><button class="btn full" type="submit">Save appointment</button></form>`);break;case'appointment-delete':confirmDialog('Cancel this appointment?','It will be removed from your care circle’s schedule.','appointment-delete-confirm',id);break;case'appointment-delete-confirm':S.data.appointments=S.data.appointments.filter(a=>a.id!==Number(id));persist();closeDialog();render();break;case'music':playMusic(id);break;case'export-progress':exportProgress();break}}
async function formSubmit(event){let form=event.target;if(!form.id)return;event.preventDefault();let d=new FormData(form),values=Object.fromEntries(d);try{switch(form.id){case'task-form':{let old=S.data.tasks.find(t=>t.id===Number(values.id)),type=values.type,obj={id:old?.id||Date.now(),title:values.title.trim(),time:values.time,type,icon:({Medicine:'pill',Meal:'food',Water:'drop',Activity:'brain',Exercise:'walk',Family:'phone',Appointment:'calendar',Sleep:'sun'})[type],repeat:values.repeat,priority:values.priority,active:d.has('active'),status:old?.status||'pending',completionDate:old?.completionDate||null,createdDate:old?.createdDate||dateKey()};if(old)Object.assign(old,obj);else S.data.tasks.push(obj);await persist();closeDialog();render();toast('Reminder saved.');break}case'memory-form':{let old=S.data.memories.find(m=>m.id===Number(values.id)),photo=old?.photo||null,file=d.get('photo');if(file?.size){if(file.size>1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPG, PNG or WebP photo smaller than 1 MB.');return}photo=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}let obj={id:old?.id||Date.now(),title:values.title.trim(),description:values.description.trim(),category:values.category,date:values.date,photo,art:({Family:'👨‍👩‍👧',Photos:'📷',Places:'🏡',Favorites:'🎵','Important Dates':'📅','Personal Stories':'📖'})[values.category]};if(old)Object.assign(old,obj);else S.data.memories.push(obj);await persist();closeDialog();render();toast('Memory saved.');break}case'profile-form':{for(let k of ['phone','doctorPhone','emergencyPhone'])if(values[k]&&!/^[+\d\s()-]{5,22}$/.test(values[k])){toast('Please check the phone number.');return}S.data.profile={...S.data.profile,...values,age:Number(values.age)};await persist();closeDialog();render();toast('Profile saved.');break}case'chat-form':sendChat(values.text);break;case'transcript-form':closeDialog();go('talk');sendChat(values.text);break;case'care-message-form':S.data.careMessages.push({id:Date.now(),text:values.text.trim(),role:S.role,author:S.user?.name||(S.role==='patient'?S.data.profile.name:S.role==='doctor'?S.data.profile.doctor:S.data.profile.caregiver),at:Date.now()});await persist();render();break;case'note-form':if(S.role!=='doctor')throw Error('Doctor access required');S.data.notes.push({id:Date.now(),title:values.title.trim(),body:values.body.trim(),author:S.user?.name||S.data.profile.doctor,at:Date.now()});await persist();closeDialog();render();toast('Care note saved.');break;case'appointment-form':S.data.appointments.push({id:Date.now(),...values,status:'Scheduled'});await persist();closeDialog();render();toast('Appointment saved.');break;case'auth-form':{let button=form.querySelector('button[type=submit]');button.disabled=true;try{let result=await request('/auth/'+values.mode,{method:'POST',body:values});S.user=result.user;S.data={...defaultData(),...result.data,settings:{...DEFAULT_SETTINGS,...result.data.settings}};S.role=S.user.role;S.view='home';closeDialog();render();toast('Welcome. Your care circle is ready.')}catch(e){$('#auth-error').textContent=e.message==='Service unavailable'?'Account services need the Node server. The hosted demo is still available.':e.message;button.disabled=false}break}}}catch(e){toast(e.message||'We could not save this change. Please try again.')}}
document.addEventListener('click',e=>{let target=e.target.closest('[data-nav],[data-role],[data-action],[data-filter],[data-game],[data-level],[data-card],[data-answer],[data-prompt],[data-call],[data-snooze]');if(!target)return;if(target.dataset.nav){go(target.dataset.nav);return}if(target.dataset.role){S.role=S.user?S.user.role:target.dataset.role;S.view='home';render();window.scrollTo(0,0);return}if(target.dataset.action){act(target.dataset.action,target.dataset.id);return}if(target.dataset.filter){S.filter=target.dataset.filter;render();return}if(target.dataset.game){S.gameType=target.dataset.game;S.game=null;render();return}if(target.dataset.level){startGame(S.gameType,Number(target.dataset.level));return}if(target.dataset.card!==undefined){flipCard(Number(target.dataset.card));return}if(target.dataset.answer!==undefined){let g=S.game;if(g){MM_GAMES.answer(g,g.choices[Number(target.dataset.answer)]);if(g.finished)finishGame();else render()}return}if(target.dataset.prompt){sendChat(target.dataset.prompt);return}if(target.dataset.call){emergencyDialog(target.dataset.call);return}if(target.dataset.snooze){let t=S.data.tasks.find(t=>t.id===Number(target.dataset.id));if(t){t.snoozedUntil=Date.now()+Number(target.dataset.snooze)*60000;persist();closeDialog();render();toast('Reminder snoozed.')}return}});
document.addEventListener('submit',formSubmit);document.addEventListener('change',e=>{let k=e.target.dataset.setting;if(!k)return;MM_VOICE.stop();S.data.settings[k]=e.target.type==='checkbox'?e.target.checked:['speed','volume'].includes(k)?Number(e.target.value):e.target.value;persist();render();toast('Preference saved.')});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeDialog()});
function tickClock(){if($('#clock'))$('#clock').textContent=new Date().toLocaleTimeString(lang().code,{hour:'numeric',minute:'2-digit'});if($('#game-timer')&&S.game){let secs=Math.round((Date.now()-S.game.started)/1000);$('#game-timer').textContent=String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0')}}
const fired=new Set();function checkReminders(){if(!S.role)return;let now=new Date();for(let t of S.data.tasks){if(!t.active||completed(t))continue;let [h,m]=t.time.split(':').map(Number),due=t.snoozedUntil?new Date(t.snoozedUntil):new Date(now.getFullYear(),now.getMonth(),now.getDate(),h,m);if(t.repeat==='Weekly'&&t.createdDate&&new Date(t.createdDate).getDay()!==now.getDay())continue;if(t.repeat==='Once'&&t.createdDate&&t.createdDate!==dateKey())continue;let key=t.id+'-'+dateKey()+'-'+(t.snoozedUntil||'');if(now>=due&&now-due<35000&&!fired.has(key)){fired.add(key);toast('A gentle reminder: '+taskTitle(t));if('Notification'in window&&Notification.permission==='granted')new Notification('Manas-Mitra',{body:taskTitle(t)+' · Please check your routine.'})}}}
MM_VOICE.init({settings:()=>S.data.settings,health:cloudHealth,status:v=>{S.voice=v;let el=$('#voice-status');if(el)el.textContent=voiceStatusText();let mic=$('.mic');if(mic){mic.classList.toggle('listening',v==='listening');mic.innerHTML=icon(v==='listening'?'stop':'mic',35)}},notify:toast,onTranscript:voiceTranscript});
async function init(){render();try{S.health=await request('/health',{signal:AbortSignal.timeout(2000)});if(S.health.service!=='Manas-Mitra')S.health=null;let current=await request('/auth/me');if(current.user){S.user=current.user;S.data={...defaultData(),...current.data,settings:{...DEFAULT_SETTINGS,...current.data.settings}};S.role=current.user.role;render()}}catch{}if(S.view==='talk')render()}
function registerTools(){let c=document.modelContext;if(!c?.registerTool)return;let tools=[{name:'read_daily_plan',description:'Read the active patient daily plan and recorded completion states.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {tasks:S.data.tasks.map(t=>({id:t.id,title:taskTitle(t),time:t.time,completed:completed(t)}))}}},{name:'start_cognitive_game',description:'Open one of the six cognitive games at a specific level, without marking it completed.',inputSchema:{type:'object',properties:{game:{type:'string',enum:MM_GAMES.types.map(t=>t[0])},level:{type:'integer',minimum:1,maximum:12}},required:['game','level'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!MM_GAMES.types.some(t=>t[0]===input?.game)||!Number.isInteger(input.level)||input.level<1||input.level>12)throw Error('Invalid game or level');S.role=S.role||'patient';S.view='games';startGame(input.game,input.level);return {game:input.game,level:input.level,status:'started'}}}];for(let t of tools){try{Promise.resolve(c.registerTool(t)).catch(()=>{})}catch{}}}
init();registerTools();setInterval(tickClock,1000);setInterval(checkReminders,15000);window.addEventListener('online',()=>{if(S.dirty)persist();toast('You are back online.')});window.addEventListener('offline',()=>toast('Offline. Your open plan and games are still available.'));window.addEventListener('beforeunload',()=>{MM_VOICE.stop();stopMusic()});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.MM_APP={state:S,go,render,defaultData,icon};
})();
